// Every icon the app draws, registered with Iconify up front so none is
// fetched from its API at runtime: icons render on first paint, work offline
// and need no third-party origin in the CSP. collection.json is generated by
// scripts/icons.mjs (npm run icons) from the names used in the code.

import { addCollection, type IconifyJSON } from "iconify-icon";
import collections from "./collection.json";

for (const collection of collections as unknown as IconifyJSON[])
  addCollection(collection);
